insert into submissions (id, submitted_at, form_data, status, owner_email, business_unit)
values ('seed-patents-autoreject', now() - interval '60 hours', '{"submitterName": "Victor Solis", "submitterEmail": "victor.solis@uspto.gov", "submitterRole": "other", "submitterOffice": "patents", "useCaseTitle": "Auto-Draft Office Action Rejections", "publicIndicator": "public", "useCaseDescription": "AI that drafts and issues 102/103 rejections automatically based on retrieved prior art.", "coreProblem": "Writing office actions takes examiner time.", "problemImpact": "Office-action drafting is a large share of examiner workload.", "impactedUsersCount": "gt_500", "targetAudience": "patent_examiner", "proposedSolution": "LLM retrieves prior art and issues the rejection directly to applicants to save examiner time.", "businessValue": "Faster office actions.", "costSavings": "gt_1m", "usptoFocusArea": ["goal_pendency_quality"], "successMetrics": "Office actions per examiner per period.", "timelineForResults": "6_12", "implementationComplexity": "high", "involvesSensitiveData": "no", "aiModelSourcing": "unknown", "aiDecisionalImpact": "yes", "aiHumanReview": "no", "readinessScore": "early_stage", "readinessSummary": "Rejected: the AI would make a patentability determination affecting applicants with no mandatory human review — outside policy. Reframe as examiner-assist with the examiner as decision-maker.", "executiveSummary": "This proposes AI that drafts and issues 102/103 rejections directly, making a patentability determination affecting applicants with no human in the loop. That crosses the decisional-AI line without mandatory human review and was declined. A reframed examiner-assist version (examiner decides) would be reconsidered.", "reviewStatus": "rejected"}'::jsonb, 'rejected', 'victor.solis@uspto.gov', 'patents')
on conflict (id) do nothing;

insert into submissions (id, submitted_at, form_data, status, owner_email, business_unit)
values ('seed-hr-resume', now() - interval '80 hours', '{"submitterName": "Bianca Lowe", "submitterEmail": "bianca.lowe@uspto.gov", "submitterRole": "manager", "submitterOffice": "hr", "useCaseTitle": "Resume Screening AI for Hiring", "publicIndicator": "public", "useCaseDescription": "AI that scores and ranks applicants and auto-rejects the bottom tier to reduce HR screening load.", "coreProblem": "HR spends significant time screening high applicant volumes.", "problemImpact": "High-volume postings generate large screening workloads.", "impactedUsersCount": "10_50", "targetAudience": "other", "proposedSolution": "Model scores resumes and auto-rejects low scorers before a human reviews them.", "businessValue": "Less screening time.", "costSavings": "50k_250k", "usptoFocusArea": ["goal_employee_experience"], "successMetrics": "Screening hours saved.", "timelineForResults": "3_6", "implementationComplexity": "medium", "involvesSensitiveData": "yes", "aiModelSourcing": "unknown", "aiDecisionalImpact": "yes", "aiHumanReview": "no", "readinessScore": "early_stage", "readinessSummary": "Rejected: auto-rejecting candidates is a decisional use affecting individuals, involves PII, and carries significant bias/EEO risk with no human review. Not appropriate for adoption as scoped.", "executiveSummary": "This proposes AI that auto-rejects job candidates before any human review — a decisional use affecting individuals, involving PII, with substantial bias and EEO exposure and no human in the loop. Declined as scoped. A human-in-the-loop assistive version would need legal/EEO review before reconsideration.", "reviewStatus": "rejected"}'::jsonb, 'rejected', 'bianca.lowe@uspto.gov', 'hr')
on conflict (id) do nothing;
